    8.5.0
    कुनै static closure मा एउटा instance bind गर्ने, वा अमिल्दो class hierarchy from कुनै method bind गर्ने कार्य अब deprecated गरिएको छ (यी केसहरूमा पहिले नै E_WARNING जारी गरिन्थ्यो)।

  &reftitle.examples;

   Closure::bindTo को उदाहरण


<?php

class A
{
    private $val;

    public function __construct($val)
    {
        $this->val = $val;
    }

    public function getClosure()
    {
        // Returns closure bound to this object and scope
        return function() {
            return $this->val;
        };
    }
}

$ob1 = new A(1);
$ob2 = new A(2);

$cl = $ob1->getClosure();
echo $cl(), "\n";

$cl = $cl->bindTo($ob2);
echo $cl(), "\n";

?>


